"""Original Whistler horn grips and gait guides; preserve accepted idle pixels."""
import json
from PIL import Image
import produce as p
UID='unit_thornwake_pollenhook_whistlers'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original POLLENHOOK WHISTLER from the supplied painting, fixed three-quarter camera facing SCREEN RIGHT. One slim pale bark-skinned humanoid with amber eyes, pointed ears, green and ochre leafy crown with small twig antlers, green leaf mantle and skirt, rope belt with pollen seed pouches, brown vine-wrapped leggings and bare rootlike toes. Exactly TWO arms, TWO hands, TWO legs. ONE original long crooked branch blow-horn with one broad flared bell, one smaller hooked upper branch brace and leaf ties, never a second horn. Anatomical RIGHT hand holds the mouthpiece end, anatomical LEFT hand supports near the bell; both grips remain attached and stable. Preserve horn length and topology, original hands, clothing and face throughout. Original painterly tactical game artwork, same anatomical size and camera, no plastic or live-action material. ')
PLATE=(' Entire backdrop stays uniform magenta RGB255,0,255. No floor, cast shadow, scenery, text, camera motion, cuts or zoom. Fixed foot ground contact plane y576; lifted feet may move during stepping but planted contacts cannot slide. Keep horn and all leaves inside generous canvas margins. No projectiles, particles, rings, beams, glow or new equipment. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8;return f
def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[18,2,3,4,5],[[24,1],[44,2],[70,3],[93,4]],0,'One complete reciprocal walking cycle IN PLACE. Near leg extends and plants while far leg trails; far leg passes and extends, near leg lifts and passes, then return to original ready. Hips, knees, ankles articulate; leaf mantle responds subtly. Horn remains lowered with both original hands gripping its ends, no blowing or attack. Opposite planted support and distinct near/far legs, no sliding or root travel. ',2026109701)
 recipe('attack',[18,6,7],[[35,1],[63,2]],0,'One physical short melee shove using the held horn body. Both hands pull the horn across the chest in anticipation, bend knees and thrust the same horn body SCREEN RIGHT once toward adjacent contact without bringing mouthpiece to lips. Contact with original horn bell/branch, then recover the arms and stance to ready. No firing, swing repetition or detached horn. ',2026109702)
 recipe('ranged',[18,10,12],[[43,1],[83,2]],0,'One ranged blow-horn aim and release. Both original hands raise the original horn, RIGHT hand brings mouthpiece to lips and LEFT supports near bell. Plant feet, lean slightly forward and visibly exhale once, cheeks and chest contracting for the release at about frame60. Keep bell facing right. No visible seed dart or pollen cloud; projectile is rendered by the game. Mouth leaves mouthpiece, both hands lower the same horn and return to ready. ',2026109703)
 recipe('hit',[18,13],[[46,1]],0,'One impact recoil. Chest and head recoil backward, knees bend to brace while both original hands keep the horn. Preserve two arms and both planted feet. Recover continuously to the original upright ready, do not fall or fire. ',2026109704)
 recipe('defend',[18,8],[],1,'One defensive brace transition. Bend both knees and lower the torso, draw the held horn horizontally across chest with both hands, then settle into compact guarded crouch. Keep original horn and grips; no aiming at lips, firing or attack. End in the original braced guard and hold during final second. ',2026109705)
 recipe('cast',[18],[],0,'One physical NONMAGICAL support gesture: while both feet stay planted and both hands keep their exact horn grips, deliberately lift the crooked horn diagonally upward so the flared bell points thirty degrees above SCREEN RIGHT as a clear rally salute above the shoulder. Both elbows rise and chest leans forward slightly, head nods once, then both hands lower the same horn back to original ready. Articulate both shoulders, elbows and wrists visibly; mouth stays away from mouthpiece throughout. No firing, spellcasting or extra arm. ',2026109706)
 recipe('death',[18,14,15,17],[[39,1],[70,2]],3,'One continuous grounded collapse. Knees buckle, torso lowers onto knees, then falls coherently onto the original side. Both hands release the same horn as body loses support; original horn settles flat beside body. Preserve exactly two arms and two legs throughout, no third hand, shrinking or disintegration. Leaf crown, mantle, rope pods and horn remain recognizable. Finish in original prone corpse guide with eyes closed, all body and equipment grounded y576, final second still. ',2026109707)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Original identity,26 source poses and8 accepted idle frames personally inspected; preserve original idle/map pixels and240ms timing. Seven new actions require chronological/enlarged/native/reflected/runtime acceptance.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,canvas=[960,640],ground_anchor=[480,576],output_scale=.5,ready_guide=reference(18),corpse_guide=reference(17),reason='One original scale per painting divided by fixed extraction scale; fixed anatomical ground plane, no per-frame normalization.'))
